import React, { useState, useEffect } from 'react';
import AdminLayout from '../../../layouts/AdminLayout';
import { useUsers } from '../hooks/useUsers';
import { fetchUsers } from '../api/userServices';
import { UserTable } from '../components/Table';

// Named export for the interface (useful for other files)
export interface User {
  id: string | number;
  name: string;
  email: string;
  role: string;
}

const Users: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const { searchTerm, setSearchTerm, filteredAndSortedUsers, requestSort } = useUsers(users);

  useEffect(() => {
    // Handling the promise from fetchUsers properly
    fetchUsers().then((data) => {
      setUsers(data as User[]);
    });
  }, []);

  return (
    <AdminLayout>
      <div style={{ padding: 24 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <h2 style={{ margin: 0 }}>🔐 Users</h2>
          <input 
            type="text" 
            placeholder="Search users..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{ padding: '8px 12px', borderRadius: '6px', border: '1px solid #CBD5E1', width: '250px' }}
          />
        </div>

        <UserTable 
          data={filteredAndSortedUsers} 
          onSort={requestSort}
          columns={[
            { label: 'Name', key: 'name' },
            { label: 'Email', key: 'email' },
            { label: 'Role', key: 'role' }
          ]}
        />
      </div>
    </AdminLayout>
  );
};

// CRITICAL: This is the default export your App.tsx is looking for
export default Users;
